Add-Type -AssemblyName System.IO.Compression.FileSystem
foreach ($f in @("1.rwmod","2.rwmod","3.zip")) {
  $p = Join-Path "F:\@AI-workshop\rwmod" $f
  Write-Output "===== $f ====="
  try {
    $zip = [System.IO.Compression.ZipFile]::OpenRead($p)
    $zip.Entries | ForEach-Object { "{0,-60} {1,10} (c={2})" -f $_.FullName, $_.Length, $_.CompressedLength }
    $zip.Dispose()
  } catch { Write-Output "ERR: $_" }
  Write-Output ""
}

