    })
}
pub fn find_define_end(src: &str, i: usize) -> Option<usize> {
    if i < src.len() {
        return src.chars().position(|x: char| {
            x != '.' && x != '_' && (x < '0' || x > '9') && (x < 'a' || x > 'z') &&
