import os, sys, io, collections
sys.stdout = io.TextIOWrapper(sys.stdout.buffer, encoding='utf-8', errors='replace')

roots = sys.argv[1:]
stats = collections.Counter()
examples = {}

def note(k, path, line=None):
    stats[k]+=1
    if k not in examples:
        examples[k]=(path, line)

for root in roots:
    for dp, dn, fn in os.walk(root):
        for f in fn:
            if not f.lower().endswith('.ini') and not f == 'mod-info.txt' and not f.endswith('.template'):
                continue
            p = os.path.join(dp,f)
            try:
                raw = open(p,'rb').read()
            except Exception:
                continue
            if b'\r\n' in raw: stats['crlf']+=1
            try:
                text = raw.decode('utf-8')
            except UnicodeDecodeError:
                note('non-utf8', p)
                text = raw.decode('utf-8','replace')
            if '"""' in text: note('triplequote', p)
            lines = text.split('\n')
            seckeys = collections.OrderedDict()
            cur=None
            for ln, line in enumerate(lines,1):
                s=line.strip()
                if s=='' or s.startswith('#'): continue
                if s.startswith('"'): note('line_starts_quote', p, s)
                if s.startswith('[') and s.endswith(']'):
                    name=s[1:-1].strip()
                    if name.startswith('comment_'): note('comment_section', p, s)
                    if name in seckeys: note('dup_section', p, s)
                    else: seckeys[name]=[]
                    cur=name
                else:
                    if '=' in s and (':' not in s or s.index('=') < s.index(':')):
                        note('equals', p, s)
                    sep = min([x for x in [s.find(':'), s.find('=')] if x>=0], default=-1)
                    if sep<0:
                        note('no_sep', p, s); continue
                    key=s[:sep].strip(); val=s[sep+1:].strip()
                    if key=='': note('empty_key', p, s)
                    if cur is None: note('key_before_section', p, s)
                    else:
                        if key in seckeys[cur]: note('dup_key', p, s)
                        else: seckeys[cur].append(key)

for k,v in sorted(stats.items()):
    print(f"{k:22} {v}")
print("---- examples ----")
for k,(p,l) in examples.items():
    print(f"{k}: {l}   @ {p}")

