import os, re, sys, io, collections
sys.stdout = io.TextIOWrapper(sys.stdout.buffer, encoding='utf-8', errors='replace')

roots = sys.argv[1:]
cnt = collections.Counter()
ex = {}
exlist = collections.defaultdict(list)

for root in roots:
    for dp, dn, fn in os.walk(root):
        for f in fn:
            if not (f.lower().endswith(('.ini', '.template')) or f.lower().endswith('mod-info.txt')):
                continue
            p = os.path.join(dp, f)
            t = open(p, 'rb').read().decode('utf-8', 'replace')
            for line in t.split('\n'):
                s = line.strip()
                if s.startswith('#') or s.startswith('"'):
                    continue
                low = s.lower()
                if low.startswith('copyfrom') and not low.startswith('copyfrom_'):
                    cnt['file_copyFrom'] += 1
                    if len(exlist['file_copyFrom']) < 8: exlist['file_copyFrom'].append(s)
                if low.startswith('@copyfromsection'):
                    cnt['@copyFromSection'] += 1
                    if len(exlist['@copyFromSection']) < 8: exlist['@copyFromSection'].append(s)
                if low.startswith('@copyfrom_skipthis'):
                    cnt['skip'] += 1
                if low.startswith('@define'):
                    cnt['@define'] += 1
                    if len(exlist['@define']) < 5: exlist['@define'].append(s)
                if low.startswith('@global'):
                    cnt['@global'] += 1
                    if len(exlist['@global']) < 5: exlist['@global'].append(s)
                if '${' in s:
                    cnt['macro_line'] += 1
                    if len(exlist['macro_line']) < 8: exlist['macro_line'].append(s)
                if low.startswith('dont_load'):
                    cnt['dont_load'] += 1

for k, v in cnt.items():
    print(k, v)
print('---')
for k, v in exlist.items():
    print(k)
    for s in v:
        print('   ', s)

