        return acc

    def resolve_section_copies(self, sections):
        resolved = {}
        visiting = set()

        def ensure(name):
            if name in resolved:
                return
            if name in visiting:
                return
            sec = sections.get(name)
            if sec is None:
                resolved[name] = None
                return
            visiting.add(name)
            target = sec.get("@copyFromSection")
            copied = OrderedDict()
            if target and target.strip().upper() != "IGNORE":
                for token in target.split(","):
                    token = token.strip()
                    if not token:
                        continue
                    ensure(token)
                    tsec = resolved.get(token)
                    if tsec:
                        copied.update(tsec)     # later target wins
            merged = OrderedDict(copied)
            for k, v in sec.items():            # own keys win
                if k == "@copyFromSection":
