        c['files'] += 1
        t = open(os.path.join(dp, f), 'rb').read().decode('utf-8', 'replace')
        for line in t.split('\n'):
            s = line.strip().lower()
            if s.startswith('@define '):
                c['@define'] += 1
            if s.startswith('@global '):
                c['@global'] += 1
            if s.startswith('copyfrom:'):
                c['copyFrom'] += 1
            if s.startswith('@copyfromsection:'):
                c['@copyFromSection'] += 1
        if '${' in t:
            c['macro'] += 1
print(c)

