def find_target(cur, token, root):
    t = token.replace('\\', '/').strip()
    if t.upper().startswith('CORE:'):
        return None
    if t.startswith('ROOT:'):
        cand = t[5:]
    else:
        d = cur.rsplit('/', 1)[0] + '/' if '/' in cur else ''
        cand = d + t
    parts = []
    for seg in cand.split('/'):
        if seg in ('', '.'):
            continue
        if seg == '..':
            if parts:
                parts.pop()
            continue
        parts.append(seg)
    p = '/'.join(parts)
    for c in (p, p + '.ini', p + '.template'):
        if c in names:
            return c
    return None

