def merge_into(dst, src, skip_dont_load=False):
    """Merge src into dst with dst's existing keys taking precedence.

    Mirrors the engine's putIfAbsent merge, including the
    '@copyFrom_skipThisSection' guard on the section already present.

    ``skip_dont_load`` is used when merging inherited sources (copyFrom /
    all-units.template): 'dont_load' only ever belongs to the file itself and
    must not be inherited, otherwise a copied unit would stop loading.
    """
    for secname, kv in src.items():
        skip = skip_dont_load and secname == "core"
        if secname not in dst:
            dst[secname] = OrderedDict(
