                if not (skip and k == "dont_load"))
            continue
        if truthy(dst[secname].get("@copyFrom_skipThisSection")):
            continue
        for k, v in kv.items():
            if skip and k == "dont_load":
                continue
            dst[secname].setdefault(k, v)

