KEYLIST = r'F:\@AI-workshop\rwmod\keyList.txt'
MODS = [r'F:\@AI-workshop\rwmod\%d.rwmod' % i for i in (1, 2, 3, 4)]

NOTE_PREFIXES = ('TYPE含', '[animationKey]同', 'N为任意内容',
                 '可以存在于任何节', 'X为任意英文内容')

GLOBAL_PLAIN = {'@copyFromSection', '@copyFrom_skipThisSection'}
GLOBAL_PREFIX = ('@define ', '@global ')

HEADER_RE = re.compile(r'^(?:\[[^\]]+\])+$')


def parse_keylist(path):
    groups = []          # list of (list_of_header_tokens, list_of_keys)
    cur_headers = None
    cur_keys = None
    with open(path, 'rb') as f:
        text = f.read().decode('utf-8-sig')
    for raw in text.split('\n'):
        line = raw.strip()
        if line == '':
            continue
        if line in NOTE_PREFIXES or line.startswith('X为任意英文'):
            continue
        if HEADER_RE.match(line):
            toks = re.findall(r'\[([^\]]+)\]', line)
            groups.append((toks, []))
            cur_headers, cur_keys = groups[-1]
            continue
        if cur_keys is None:
            continue
        if line.startswith('TYPE含') or line.startswith('[animationKey]同'):
            continue
        cur_keys.append(line)
    return groups


def section_group(toks, section):
    for tok in toks:
        if tok == section:
            return True
        if tok.endswith('_NAME') or tok.endswith('_NANE'):
            prefix = tok.rsplit('_', 1)[0]
            if section.startswith(prefix + '_'):
                return True
            if prefix == 'hiddenAction' and section.startswith('action_'):
                return True
        if tok.endswith('_#'):
            prefix = tok.rsplit('_', 1)[0]
            if section.startswith(prefix + '_'):
                return True
    return False


def key_regex(pat, action_keys, canbuild_keys):
    p = pat
    if 'name/pos/isLocked:' in p:
        return None
    p = p.replace('[Language]', r'.+')
    p = p.replace('[actionKey]', '(' + '|'.join(re.escape(k) for k in action_keys) + ')')
    p = p.replace('[canBuildKey]', '(' + '|'.join(re.escape(k) for k in canbuild_keys) + ')')
    p = p.replace('[animationKey]', r'.+')
    p = p.replace('[time]', r'.+')
    p = p.replace('animation_TYPE_', r'animation_(idle|moving|attack)_')
    p = p.replace('mutatorN_', r'mutator.*_')
    p = p.replace('#', r'\d*')
    return '^' + re.escape(p).replace(r'\[', '[').replace(r'\]', ']') + '$'


def build_matcher(groups):
    # collect action / canBuild keys for placeholders
    action_keys, canbuild_keys = set(), set()
    for toks, keys in groups:
        if 'hiddenAction_NAME' in toks:
            action_keys.update(keys)
        if 'canBuild_NAME' in toks:
            canbuild_keys.update(keys)
    # section -> list of regexes
    regs = {}
    for toks, keys in groups:
        rx = []
        for k in keys:
            if 'name/pos/isLocked:' in k:
                base = k.split('name/pos/isLocked:')[0]
                for suf in ('name', 'pos', 'isLocked'):
                    r = key_regex(base + suf, action_keys, canbuild_keys)
                    if r:
                        rx.append(r)
                continue
            r = key_regex(k, action_keys, canbuild_keys)
            if r:
                rx.append(r)
        for tok in toks:
            regs.setdefault(tok, []).extend(rx)
    return regs, action_keys, canbuild_keys


def legal(section, key, groups, globals_ok):
    if key in GLOBAL_PLAIN:
        return True
    if key.startswith('@define ') or key.startswith('@global '):
        return True
    if key.startswith('@memory'):
        return True
    for toks, keys in groups:
        if not section_group(toks, section):
            continue
        for k in keys:
            if 'name/pos/isLocked:' in k:
                base = k.split('name/pos/isLocked:')[0]
                for suf in ('name', 'pos', 'isLocked'):
                    if re.match(key_regex(base + suf, GLOBAL_ACTIONS, GLOBAL_CANBUILD), key):
                        return True
                continue
            r = key_regex(k, GLOBAL_ACTIONS, GLOBAL_CANBUILD)
            if r and re.match(r, key):
                return True
    return False


def parse_ini(text):
    sections = collections.OrderedDict()
    cur = None
    for line in text.split('\n'):
        s = line.strip()
        if s == '' or s[0] == '#':
            continue
        if s[0] == '[':
            close = s.find(']', 1)
            if close == len(s) - 1:
                name = s[1:close].strip()
                if name.startswith('comment_'):
                    cur = None
                else:
                    sections.setdefault(name, collections.OrderedDict())
                    cur = name
                continue
        if cur is None:
            continue
        sp = -1
        for i, ch in enumerate(s):
            if ch in ':=':
                sp = i
                break
        if sp < 0:
            continue
        sections[cur][s[:sp].strip()] = s[sp + 1:].strip()
    return sections


