def parse_ini_crlf(text):
    lines = re.split(r'\r\n|\r|\n', text)
    sections = m.OrderedDict()
    current = None
    i = 0
    n = len(lines)
    while i < n:
        raw = lines[i]
        i += 1
        s = raw.strip().strip('\ufeff')
        if s == '' or s[0] == '#':
            continue
        skip = (s[0] == '"')
        in_quotes = False
        buf = []
        piece = s
        while True:
            j = 0
            ln = len(piece)
            while j >= 0:
                k = piece.find('"""', j)
                if k < 0:
                    mm = k; k = ln
                else:
                    in_quotes = not in_quotes; mm = k + 3
                if not skip:
                    buf.append(piece[j:k])
                j = mm
            if in_quotes:
                if i >= n:
                    break
                piece = lines[i].strip().strip('\ufeff'); i += 1
            else:
                break
        if skip:
            continue
        s = ''.join(buf).strip()
        if s == '':
            continue
        if s[0] == '[':
            close = s.find(']', 1)
            if close == len(s) - 1:
                name = s[1:close].strip().strip('\ufeff')
                if name.startswith('comment_'):
                    current = None
                else:
                    sections.setdefault(name, m.OrderedDict())
                    current = name
                continue
        if current is None:
            continue
        split = -1
        for idx, ch in enumerate(s):
            if ch in ':=':
                split = idx; break
        if split < 0:
            continue
        key = s[:split].strip().strip('\ufeff')
        value = s[split + 1:].strip().strip('\ufeff')
        sections[current][key] = value
    return sections


