def _decode_maybe_text(data):
    """Return decoded text when the bytes look like a text file, else None."""
    if not data or b"\x00" in data[:8192]:
        return None
    for enc in ("utf-8-sig", "utf-8", "gbk", "big5"):
        try:
            text = data.decode(enc)
            break
        except UnicodeDecodeError:
            continue
    else:
        return None
    sample = text[:4096]
    if sample:
        good = sum(1 for c in sample if c.isprintable() or c in "\r\n\t")
        if good / len(sample) < 0.9:
            return None
    return text


